using System.Collections.Generic;using Janseon.Core.Data;using Janseon.Data.Validation;
namespace Janseon.Data.Repositories { public sealed class FormationCatalogRepository:IReadOnlyFormationCatalog { readonly Dictionary<string,FormationCatalogItem> byId=new Dictionary<string,FormationCatalogItem>(System.StringComparer.Ordinal);public IReadOnlyList<FormationCatalogItem> All{get;}public FormationCatalogRepository(GameDataCatalogIndex i){All=i.Formations;foreach(var x in All)byId.Add(x.StableId,x);}public bool TryGet(string id,out FormationCatalogItem x)=>byId.TryGetValue(id??string.Empty,out x);}}
